INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-network-troubleshooting', 'M15', 'sonoff-installer-certification', 'Network Troubleshooting & Advanced Deployment Scenarios', 'استكشاف أعطال الشبكة وسيناريوهات النشر المتقدمة', 'Diagnosing Zigbee mesh issues, planning multi-gateway deployments for large properties, reading energy monitoring data, and security camera placement best practices.', 'تشخيص مشكلات شبكة Zigbee، تخطيط تركيبات متعددة البوابات للعقارات الكبيرة، قراءة بيانات مراقبة الطاقة، وأفضل ممارسات تموضع كاميرات المراقبة.', NULL, 15);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Diagnosing Zigbee Mesh Network Problems', 'تشخيص مشكلات شبكة Zigbee الشبكية', 'A healthy Zigbee mesh relies on enough powered (mains) devices acting as routers to relay signal between the coordinator and battery-powered end devices. When a device repeatedly drops offline, the first checks are: is it too far from the nearest router with no repeater in between, is there a 2.4GHz Wi-Fi channel directly overlapping the Zigbee channel in use, and has the device actually joined the intended network rather than a leftover pairing from a previous setup. Rebuilding a mesh''s routing table by power-cycling routers one at a time (rather than all at once) lets each router re-discover its neighbors in a controlled way and is safer than a full network reset for an occupied home.', 'تعتمد شبكة Zigbee الصحية على عدد كافٍ من الأجهزة المتصلة بالكهرباء لتعمل كموجّهات تعيد إرسال الإشارة بين المنسق والأجهزة الطرفية العاملة بالبطارية. عندما ينقطع جهاز بشكل متكرر، الفحوصات الأولى هي: هل هو بعيد جدًا عن أقرب موجّه دون معيد إشارة بينهما، هل توجد قناة Wi-Fi بتردد 2.4 جيجاهرتز تتداخل مباشرة مع قناة Zigbee المستخدمة، وهل انضم الجهاز فعليًا للشبكة المقصودة لا لإقران متبقٍ من إعداد سابق. إعادة بناء جدول التوجيه للشبكة عبر إعادة تشغيل الموجّهات واحدًا تلو الآخر (لا جميعها دفعة واحدة) يتيح لكل موجّه اكتشاف جيرانه بشكل منضبط وأكثر أمانًا من إعادة ضبط الشبكة بالكامل في منزل مأهول.', 1 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Multi-Gateway Deployments for Larger Properties', 'تركيبات متعددة البوابات للعقارات الكبيرة', 'Large homes or commercial spaces sometimes need more than one gateway to maintain reliable coverage. When deploying multiple gateways on the same protocol, each should be assigned a distinct, non-overlapping channel where the platform allows it, and installers must decide whether the gateways operate as independent networks (simpler, but no shared automations across zones) or a single extended network (requires more careful channel and PAN ID planning). Documenting which gateway owns which physical zone prevents confusion during future maintenance visits.', 'المنازل الكبيرة أو المساحات التجارية تحتاج أحيانًا أكثر من بوابة واحدة للحفاظ على تغطية موثوقة. عند نشر بوابات متعددة على نفس البروتوكول، يجب تخصيص قناة مميزة وغير متداخلة لكل بوابة حيثما تسمح المنصة، ويجب على الفني تحديد ما إذا كانت البوابات تعمل كشبكات مستقلة (أبسط، لكن بلا أتمتة مشتركة بين المناطق) أو شبكة موسّعة واحدة (تتطلب تخطيطًا أدق للقناة ومعرف الشبكة). توثيق البوابة المسؤولة عن كل منطقة فعلية يمنع الالتباس في زيارات الصيانة المستقبلية.', 2 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Energy Monitoring: Reading and Acting on Power Data', 'مراقبة الطاقة: قراءة بيانات الاستهلاك والتصرف بناءً عليها', 'Devices with built-in energy monitoring report metrics like instantaneous power, accumulated energy, voltage, and current. Installers should help customers set realistic alert thresholds — for example, flagging a load that stays on unusually long, or a spike suggesting a failing appliance motor — rather than leaving default thresholds that generate noise. Calibration matters too: comparing the device''s reading against a known reference load during commissioning catches sensor drift before the customer starts relying on the numbers for billing estimates.', 'الأجهزة المزودة بمراقبة طاقة مدمجة تُبلغ عن مقاييس مثل القدرة اللحظية والطاقة المتراكمة والجهد والتيار. يجب على الفني مساعدة العميل على ضبط عتبات تنبيه واقعية — مثل الإبلاغ عن حمل يبقى قيد التشغيل لفترة غير معتادة، أو ارتفاع مفاجئ يشير لعطل في محرك جهاز — بدلًا من ترك العتبات الافتراضية التي تولّد إشعارات كثيرة غير مفيدة. المعايرة مهمة أيضًا: مقارنة قراءة الجهاز بحمل مرجعي معروف أثناء التشغيل تكشف انحراف الحساس قبل أن يعتمد العميل على الأرقام لتقدير الفواتير.', 3 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Security Camera Installation: Placement & Privacy Considerations', 'تركيب كاميرات المراقبة: اعتبارات الموضع والخصوصية', 'Camera placement should balance coverage against glare, backlighting, and privacy boundaries — a camera facing directly into morning or evening sun will wash out footage at exactly the times it matters most. Installers should angle cameras to avoid capturing neighboring properties or public streets beyond what''s needed for the customer''s own security, check local regulations on recording audio (which often differ from rules on video), and set motion-zone masking to reduce false alerts from swaying trees or passing traffic rather than leaving whole-frame detection active.', 'يجب أن يوازن موضع الكاميرا بين التغطية والوهج والإضاءة الخلفية وحدود الخصوصية — كاميرا تواجه شمس الصباح أو المساء مباشرة ستفقد وضوح التسجيل في أهم الأوقات بالضبط. يجب على الفني توجيه الكاميرات لتفادي تصوير الممتلكات المجاورة أو الشوارع العامة بما يتجاوز حاجة أمن العميل الفعلية، والتحقق من اللوائح المحلية بشأن تسجيل الصوت (التي غالبًا تختلف عن قواعد الفيديو)، وضبط إخفاء مناطق الحركة لتقليل التنبيهات الكاذبة من الأشجار المتمايلة أو المرور بدلًا من ترك كشف الإطار الكامل نشطًا.', 4 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', title || ' — Bronze Quiz', title_ar || ' — اختبار برونزي', 80 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'When troubleshooting a Zigbee device that keeps dropping offline, what should be checked first?', 'عند تشخيص جهاز Zigbee ينقطع باستمرار، ما الذي يجب فحصه أولًا؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Distance from the nearest router and possible Wi-Fi channel overlap', 'المسافة عن أقرب موجّه واحتمال تداخل قناة Wi-Fi', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'When troubleshooting a Zigbee device that keeps dropping offline, what should be checked first?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The color of the device''s plastic housing', 'لون هيكل الجهاز البلاستيكي', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'When troubleshooting a Zigbee device that keeps dropping offline, what should be checked first?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The customer''s electricity bill amount', 'قيمة فاتورة كهرباء العميل', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'When troubleshooting a Zigbee device that keeps dropping offline, what should be checked first?';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'Why should motion-zone masking be configured on security cameras rather than leaving whole-frame detection active?', 'لماذا يجب ضبط إخفاء مناطق الحركة على كاميرات المراقبة بدلًا من ترك كشف الإطار الكامل نشطًا؟', 2 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'To reduce false alerts from trees, traffic, or other irrelevant movement', 'لتقليل التنبيهات الكاذبة من الأشجار أو المرور أو الحركة غير ذات الصلة', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why should motion-zone masking be configured on security cameras rather than leaving whole-frame detection active?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'It has no impact on alert accuracy', 'لا تأثير له على دقة التنبيهات', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why should motion-zone masking be configured on security cameras rather than leaving whole-frame detection active?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'It only affects video resolution', 'يؤثر فقط على دقة الفيديو', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why should motion-zone masking be configured on security cameras rather than leaving whole-frame detection active?';
